    for (let left = 0; left + len < n; left++) {
      const right = left + len;
      for (let k = left + 1; k < right; k++) {
        dp[left][right] = Math.max(
          dp[left][right],
          balloons[left] * balloons[k] * balloons[right] + dp[left][k] + dp[k][right]
        );
      }
    }
  }
  return dp[0][n - 1];
}

